"""The tools the model can call, confined to one project checkout.

Which tools may write where depends on the phase:
  read       - nothing is written
  reproduce  - only test files may be written
  fix        - only non-test files may be written
The tool list itself never changes between phases (that keeps the prompt cache
warm); the workspace refuses calls the current phase does not allow.
"""

from __future__ import annotations

import os
import re
import subprocess
import sys
from pathlib import Path
from typing import Any, Callable

from . import tracing
from .pytest_run import clip, run_pytest

READ, REPRODUCE, FIX = "read", "reproduce", "fix"

_SKIP_DIRS = {".git", ".venv", "venv", ".tox", "__pycache__", "node_modules", ".mypy_cache", ".pytest_cache", "build", "dist"}


def is_test_path(rel: str) -> bool:
    parts = Path(rel.replace("\\", "/")).parts
    if not parts:
        return False
    name = parts[-1]
    return (
        any(p in ("tests", "testing", "test") for p in parts[:-1])
        or name.startswith("test_")
        or name.endswith("_test.py")
        or name == "conftest.py"
    )


class ToolError(Exception):
    pass


# Never hand these to the project under test: its code and the model's commands run there.
SECRET_VARS = ("ANTHROPIC_API_KEY", "WINCHECK_ANTHROPIC_API_KEY", "ANTHROPIC_AUTH_TOKEN", "NEATLOGS_API_KEY",
               "GITHUB_TOKEN", "GH_TOKEN", "AWS_ACCESS_KEY_ID", "AWS_SECRET_ACCESS_KEY", "AWS_SESSION_TOKEN")


def scrub(env: dict[str, str]) -> dict[str, str]:
    return {k: v for k, v in env.items() if k.upper() not in SECRET_VARS}


class Workspace:
    def __init__(self, root: Path, python: str, env: dict[str, str] | None = None):
        self.root = root.resolve()
        self.python = python
        self.env = scrub(env or os.environ.copy())
        self.phase = READ
        # Set by the agent when a phase-changing tool is called.
        self.submission: tuple[str, dict[str, Any]] | None = None

    # -- helpers ---------------------------------------------------------
    def resolve(self, rel: str) -> Path:
        path = (self.root / rel).resolve()
        if path != self.root and self.root not in path.parents:
            raise ToolError(f"{rel!r} is outside the project")
        return path

    def rel(self, path: Path) -> str:
        return path.relative_to(self.root).as_posix()

    def check_write(self, rel: str) -> None:
        if self.phase == READ:
            raise ToolError("Nothing can be written while reading the issue. Call start_reproduction first.")
        test = is_test_path(rel)
        if self.phase == REPRODUCE and not test:
            raise ToolError(
                f"{rel} is not a test file. During reproduction only test files may change; "
                "the source stays untouched until a failing test exists."
            )
        if self.phase == FIX and test:
            raise ToolError(f"{rel} is a test file. Test files are frozen once the reproduction is accepted.")

    # -- tools -----------------------------------------------------------
    def read_file(self, path: str, start_line: int = 1, end_line: int | None = None) -> str:
        p = self.resolve(path)
        if not p.is_file():
            raise ToolError(f"{path} is not a file")
        lines = p.read_text(encoding="utf-8", errors="replace").splitlines()
        end = min(end_line or len(lines), len(lines))
        start = max(start_line, 1)
        body = "\n".join(f"{i:>5}  {lines[i - 1]}" for i in range(start, end + 1))
        return clip(f"{path} (lines {start}-{end} of {len(lines)})\n{body}", 40000)

    def list_dir(self, path: str = ".") -> str:
        p = self.resolve(path)
        if not p.is_dir():
            raise ToolError(f"{path} is not a directory")
        entries = sorted(p.iterdir(), key=lambda e: (not e.is_dir(), e.name))
        out = [e.name + ("/" if e.is_dir() else "") for e in entries if e.name not in _SKIP_DIRS]
        return "\n".join(out) or "(empty)"

    def search(self, pattern: str, path: str = ".", glob: str = "*.py") -> str:
        try:
            rx = re.compile(pattern)
        except re.error as exc:
            raise ToolError(f"bad regex: {exc}") from exc
        base = self.resolve(path)
        hits: list[str] = []
        files = [base] if base.is_file() else base.rglob(glob)
        for f in files:
            if any(part in _SKIP_DIRS for part in f.relative_to(self.root).parts):
                continue
            try:
                text = f.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            for n, line in enumerate(text.splitlines(), 1):
                if rx.search(line):
                    hits.append(f"{self.rel(f)}:{n}: {line.strip()[:200]}")
                    if len(hits) >= 200:
                        return "\n".join(hits) + "\n(stopped at 200 matches)"
        return "\n".join(hits) or "no matches"

    def write_file(self, path: str, content: str) -> str:
        self.check_write(path)
        p = self.resolve(path)
        p.parent.mkdir(parents=True, exist_ok=True)
        # newline="" keeps the line endings exactly as the model wrote them
        with open(p, "w", encoding="utf-8", newline="") as fh:
            fh.write(content)
        return f"wrote {path} ({len(content)} chars)"

    def edit_file(self, path: str, old: str, new: str) -> str:
        self.check_write(path)
        p = self.resolve(path)
        if not p.is_file():
            raise ToolError(f"{path} does not exist")
        raw = p.read_bytes().decode("utf-8")
        crlf = "\r\n" in raw
        text = raw.replace("\r\n", "\n") if crlf else raw
        count = text.count(old)
        if count != 1:
            raise ToolError(f"`old` must match exactly once in {path}; it matched {count} times")
        text = text.replace(old, new, 1)
        if crlf:
            text = text.replace("\n", "\r\n")
        p.write_bytes(text.encode("utf-8"))
        return f"edited {path}"

    def run_command(self, command: str, timeout: int = 300) -> str:
        if self.phase == READ:
            raise ToolError("Commands can be run from the reproduction phase on. Call start_reproduction first.")
        try:
            proc = subprocess.run(
                command,
                shell=True,
                cwd=self.root,
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=min(timeout, 900),
                env=self.env,
            )
        except subprocess.TimeoutExpired:
            return f"timed out after {timeout}s"
        return clip(f"exit code {proc.returncode}\n{proc.stdout}\n{proc.stderr}")

    def run_tests(self, test_ids: list[str]) -> str:
        if self.phase == READ:
            raise ToolError("Tests can be run from the reproduction phase on. Call start_reproduction first.")
        res = run_pytest(self.python, self.root, test_ids, env=self.env)
        summary = "\n".join(f"{v:7} {k}" for k, v in res.outcomes.items()) or "(no per-test results)"
        return clip(f"exit code {res.returncode}\n{summary}\n\n--- output ---\n{res.output}")

    # Phase changes. These only record the request; the agent loop checks it.
    def start_reproduction(self, plan: str) -> str:
        if self.phase != READ:
            raise ToolError("Already past the read phase.")
        self.submission = ("start_reproduction", {"plan": plan})
        return "ok"

    def submit_reproduction(self, test_ids: list[str], explanation: str) -> str:
        if self.phase != REPRODUCE:
            raise ToolError("submit_reproduction is only valid during reproduction.")
        bad = [t for t in test_ids if not is_test_path(t.split("::", 1)[0])]
        if not test_ids or bad:
            raise ToolError(f"Give pytest node ids inside test files. Rejected: {bad or 'empty list'}")
        self.submission = ("submit_reproduction", {"test_ids": test_ids, "explanation": explanation})
        return "submitted; the harness will run these tests now"

    def submit_fix(self, summary: str) -> str:
        if self.phase != FIX:
            raise ToolError("submit_fix is only valid during the fix phase.")
        self.submission = ("submit_fix", {"summary": summary})
        return "submitted; the harness will verify now"

    def give_up(self, reason: str) -> str:
        self.submission = ("give_up", {"reason": reason})
        return "ok"


def _schema(props: dict[str, Any], required: list[str]) -> dict[str, Any]:
    return {"type": "object", "properties": props, "required": required, "additionalProperties": False}


_S = {"type": "string"}
_I = {"type": "integer"}
_IDS = {"type": "array", "items": {"type": "string"}}

TOOL_SPECS: list[dict[str, Any]] = [
    {"name": "read_file", "description": "Read a text file from the project, with line numbers. Optionally a line range.",
     "input_schema": _schema({"path": _S, "start_line": _I, "end_line": _I}, ["path"])},
    {"name": "list_dir", "description": "List a directory in the project.",
     "input_schema": _schema({"path": _S}, [])},
    {"name": "search", "description": "Regex search over project files (default *.py). Returns path:line: text.",
     "input_schema": _schema({"pattern": _S, "path": _S, "glob": _S}, ["pattern"])},
    {"name": "write_file", "description": "Create or overwrite a file. Content is written byte for byte (no newline translation).",
     "input_schema": _schema({"path": _S, "content": _S}, ["path", "content"])},
    {"name": "edit_file", "description": "Replace one exact occurrence of `old` with `new` in a file. Line endings of the file are preserved.",
     "input_schema": _schema({"path": _S, "old": _S, "new": _S}, ["path", "old", "new"])},
    {"name": "run_command", "description": "Run a shell command in the project root, inside the project's virtualenv. Returns exit code and output.",
     "input_schema": _schema({"command": _S, "timeout": _I}, ["command"])},
    {"name": "run_tests", "description": "Run pytest node ids (e.g. tests/test_x.py::test_y) and get per-test outcomes plus output.",
     "input_schema": _schema({"test_ids": _IDS}, ["test_ids"])},
    {"name": "start_reproduction", "description": "Leave the read phase. Say what the bug is and how you will reproduce it.",
     "input_schema": _schema({"plan": _S}, ["plan"])},
    {"name": "submit_reproduction", "description": "Submit the pytest node ids that reproduce the bug. The harness runs them; every one must FAIL on this machine for the reproduction to be accepted.",
     "input_schema": _schema({"test_ids": _IDS, "explanation": _S}, ["test_ids", "explanation"])},
    {"name": "submit_fix", "description": "Submit the fix. The harness re-runs the reproduction tests (must pass) and the test files they live in (no new failures).",
     "input_schema": _schema({"summary": _S}, ["summary"])},
    {"name": "give_up", "description": "Stop without a patch, e.g. when the bug cannot be reproduced on this machine. Explain why.",
     "input_schema": _schema({"reason": _S}, ["reason"])},
]

for _spec in TOOL_SPECS:
    _spec["eager_input_streaming"] = True


def validate_input(spec: dict[str, Any], data: Any) -> str | None:
    """Check a (possibly truncated) streamed tool input against its schema."""
    if not isinstance(data, dict):
        return "input is not a JSON object"
    schema = spec["input_schema"]
    for key in schema["required"]:
        if key not in data:
            return f"missing required field {key!r}"
    for key, value in data.items():
        prop = schema["properties"].get(key)
        if prop is None:
            return f"unknown field {key!r}"
        kind = prop["type"]
        ok = (
            (kind == "string" and isinstance(value, str))
            or (kind == "integer" and isinstance(value, int) and not isinstance(value, bool))
            or (kind == "array" and isinstance(value, list) and all(isinstance(v, str) for v in value))
        )
        if not ok:
            return f"field {key!r} should be {kind}"
    return None


def build_dispatch(ws: Workspace) -> dict[str, Callable[..., str]]:
    """Map tool names to workspace methods, each wrapped in a neatlogs TOOL span."""
    return {
        spec["name"]: tracing.span(kind="TOOL", name=spec["name"], tool_name=spec["name"])(getattr(ws, spec["name"]))
        for spec in TOOL_SPECS
    }


def venv_python(venv: Path) -> str:
    sub = "Scripts/python.exe" if sys.platform == "win32" else "bin/python"
    return str(venv / sub)

"""The Wincheck agent: read the issue, reproduce it, fix it, verify the fix.

The model drives each phase with tools; the harness owns the gates between
phases. A reproduction is only accepted when the harness itself sees every
submitted test fail, and a fix is only accepted when those tests pass and the
test files they live in have no new failures. Without an accepted
reproduction, nothing outside the test files can be changed.
"""

from __future__ import annotations

import json
import os
import platform
import subprocess
import sys
import time
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any

import anthropic

from . import tracing
from .pytest_run import clip, run_pytest
from .tools import FIX, READ, REPRODUCE, TOOL_SPECS, ToolError, Workspace, build_dispatch, is_test_path, validate_input

MODEL = "claude-opus-5-5"
# Hosts that reserve ANTHROPIC_API_KEY for their own login (Claude Code cloud
# sessions) may not pass it through, so the agent also accepts its own name.
API_KEY_VARS = ("ANTHROPIC_API_KEY", "WINCHECK_ANTHROPIC_API_KEY")


def api_key() -> str | None:
    return next((os.environ[v] for v in API_KEY_VARS if os.environ.get(v)), None)
SPECS_BY_NAME = {s["name"]: s for s in TOOL_SPECS}

SYSTEM = """You are Wincheck, an engineer who fixes Windows-specific bugs in Python projects.

You are given an issue report and a checkout of the project at the commit where the bug exists. You work in three phases, and a harness enforces the gates between them:

1. read - explore the code and the issue. Nothing can be written or run yet. Call start_reproduction when you understand the bug well enough to test it.
2. reproduce - write pytest tests that fail because of the bug, then call submit_reproduction with their node ids. Only test files can be written. The harness runs the tests itself and accepts the reproduction only if every one of them fails on this machine. Prefer adding a focused test to the project's existing test file for that area, written in the project's style, so it can stay in the codebase as a regression test. The test must fail for the reason in the issue, not because of a typo or an import error.
3. fix - change the project's source so the reproduction passes. Test files are frozen. Call submit_fix when done; the harness re-runs the reproduction (all must pass) and the whole test files they live in (no test that passed before may fail now). If verification fails you get the output and can try again.

If the bug does not reproduce on this machine after a genuine attempt, call give_up and explain what you tried. Never patch code without a reproduction.

Keep the fix as small as the bug allows and match the surrounding code. Fix the root cause in the code path the project already uses: reuse its existing helpers and APIs instead of adding a new one or bypassing them, because callers and tests rely on those paths. Prefer one simple, consistent rule over special cases. If the bug comes from a rule that is wrong on Windows, correct the rule for every input it covers, rather than keeping the old behaviour for edge cases that no existing test or documentation asks for. Think about how Windows differs: path separators and drive letters, CRLF line endings and text-mode newline translation, file locking (an open file cannot be deleted or replaced), case-insensitive paths, the console encoding, MAX_PATH, process spawning and signals, and shell quoting.
"""


@dataclass
class AgentResult:
    status: str = "running"  # fixed | unverified | no_repro | gave_up | error
    reason: str = ""
    repro_tests: list[str] = field(default_factory=list)
    repro_explanation: str = ""
    fix_summary: str = ""
    fix_attempts: int = 0
    diff: str = ""
    turns: int = 0
    usage: dict[str, int] = field(default_factory=dict)
    seconds: float = 0.0
    platform: str = field(default_factory=lambda: f"{platform.system()} {platform.release()} / Python {platform.python_version()}")


class Agent:
    def __init__(
        self,
        ws: Workspace,
        issue: str,
        run_dir: Path,
        model: str = MODEL,
        effort: str = "high",
        max_turns_per_phase: int = 40,
        max_fix_attempts: int = 3,
        client: anthropic.Anthropic | None = None,
    ):
        self.ws = ws
        self.issue = issue
        self.run_dir = run_dir
        self.model = model
        self.effort = effort
        self.max_turns = max_turns_per_phase
        self.max_fix_attempts = max_fix_attempts
        self.client = client or anthropic.Anthropic(api_key=api_key(), max_retries=4)
        self.tools = build_dispatch(ws)
        self.messages: list[dict[str, Any]] = []
        self.result = AgentResult()
        self.test_snapshot: dict[str, bytes | None] = {}
        self.baseline: dict[str, str] = {}
        self._log = None

    # -- top level -------------------------------------------------------
    @tracing.span(kind="WORKFLOW", name="wincheck_run", capture_input=False)
    def run(self) -> AgentResult:
        start = time.monotonic()
        self.run_dir.mkdir(parents=True, exist_ok=True)
        self._log = open(self.run_dir / "transcript.jsonl", "w", encoding="utf-8")
        self.messages.append({"role": "user", "content": self._opening()})
        try:
            if self._read_phase() and self._reproduce_phase():
                self._fix_phase()
        except _Stop as stop:
            self.result.status, self.result.reason = stop.status, stop.reason
        except anthropic.APIError as exc:
            self.result.status, self.result.reason = "error", f"API error: {exc}"
        finally:
            self.result.diff = self._diff()
            self.result.seconds = round(time.monotonic() - start, 1)
            self._log.close()
            (self.run_dir / "result.json").write_text(json.dumps(asdict(self.result), indent=2), encoding="utf-8")
            (self.run_dir / "fix.patch").write_text(self.result.diff, encoding="utf-8")
        return self.result

    def _opening(self) -> str:
        return (
            f"Machine: {self.result.platform} ({sys.platform}). Shell for run_command: "
            f"{'cmd.exe' if sys.platform == 'win32' else 'sh'}. The project's virtualenv is active for "
            f"run_command and run_tests.\n\nPhase: read.\n\n<issue>\n{self.issue}\n</issue>"
        )

    # -- phases ----------------------------------------------------------
    @tracing.span(kind="AGENT", name="read_issue", capture_input=False, role="reader", goal="Understand the bug from the issue and the code")
    def _read_phase(self) -> bool:
        self.ws.phase = READ
        kind, _ = self._converse(READ, {"start_reproduction"})
        if kind == "give_up":
            return False
        self.ws.phase = REPRODUCE
        self._note("Phase: reproduce. You can now write test files and run commands and tests.")
        return True

    @tracing.span(kind="AGENT", name="reproduce", capture_input=False, role="reproducer", goal="Write tests that fail because of the bug")
    def _reproduce_phase(self) -> bool:
        while True:
            kind, data = self._converse(REPRODUCE, {"submit_reproduction"})
            if kind == "give_up":
                self.result.status = "no_repro"
                return False
            ok, report = self._check_reproduction(data["test_ids"])
            if ok:
                self.result.repro_tests = data["test_ids"]
                self.result.repro_explanation = data["explanation"]
                self.ws.phase = FIX
                self._note(f"Reproduction accepted.\n{report}\n\nPhase: fix. Test files are now frozen; change the source.")
                return True
            self._note(f"Reproduction rejected: every submitted test must FAIL.\n{report}")

    @tracing.span(kind="AGENT", name="fix_and_verify", capture_input=False, role="fixer", goal="Make the reproduction pass without regressions")
    def _fix_phase(self) -> None:
        while True:
            kind, data = self._converse(FIX, {"submit_fix"})
            if kind == "give_up":
                return
            self.result.fix_attempts += 1
            self.result.fix_summary = data["summary"]
            ok, report = self._verify()
            if ok:
                self.result.status = "fixed"
                self._note(f"Fix verified.\n{report}", final=True)
                return
            if self.result.fix_attempts >= self.max_fix_attempts:
                self.result.status, self.result.reason = "unverified", report
                return
            self._note(f"Verification failed (attempt {self.result.fix_attempts} of {self.max_fix_attempts}).\n{report}")

    # -- harness gates ---------------------------------------------------
    @tracing.span(kind="TOOL", name="check_reproduction", capture_input=False, tool_name="check_reproduction")
    def _check_reproduction(self, test_ids: list[str]) -> tuple[bool, str]:
        res = run_pytest(self.ws.python, self.ws.root, test_ids, env=self.ws.env)
        outcomes = {t: res.outcome(t) for t in test_ids}
        lines = "\n".join(f"{o:7} {t}" for t, o in outcomes.items())
        if not all(o == "FAILED" for o in outcomes.values()):
            return False, f"{lines}\n\n--- output ---\n{clip(res.output, 15000)}"
        # Freeze test files and record how their whole files behave before the fix.
        self.test_snapshot = {p: self._read_bytes(p) for p in self._changed_test_files()}
        files = sorted({t.split("::", 1)[0] for t in test_ids})
        base = run_pytest(self.ws.python, self.ws.root, files, env=self.ws.env)
        self.baseline = base.outcomes
        return True, lines

    @tracing.span(kind="TOOL", name="verify_fix", capture_input=False, tool_name="verify_fix")
    def _verify(self) -> tuple[bool, str]:
        tampered = self._restore_tests()
        if tampered:
            return False, "These test files were changed during the fix phase and have been restored: " + ", ".join(tampered)
        files = sorted({t.split("::", 1)[0] for t in self.result.repro_tests})
        res = run_pytest(self.ws.python, self.ws.root, files, env=self.ws.env)
        repro = {t: res.outcome(t) for t in self.result.repro_tests}
        regressions = [
            t for t, before in self.baseline.items()
            if before == "PASSED" and res.outcome(t) not in ("PASSED", "XFAIL") and t not in repro
        ]
        lines = [f"{o:7} {t}" for t, o in repro.items()]
        if regressions:
            lines.append("New failures: " + ", ".join(regressions))
        ok = all(o == "PASSED" for o in repro.values()) and not regressions
        report = "\n".join(lines)
        if not ok:
            report += f"\n\n--- output ---\n{clip(res.output, 15000)}"
        return ok, report

    # -- conversation ----------------------------------------------------
    def _converse(self, phase: str, exits: set[str]) -> tuple[str, dict[str, Any]]:
        """Run model turns until it calls one of `exits` (or give_up)."""
        nudges = 0
        for _ in range(self.max_turns):
            msg = self._call_model()
            self.messages.append({"role": "assistant", "content": msg.content})
            if msg.stop_reason == "refusal":
                raise _Stop("error", f"model refused: {getattr(msg, 'stop_details', None)}")
            uses = [b for b in msg.content if b.type == "tool_use"]
            if not uses:
                nudges += 1
                if nudges > 3:
                    raise _Stop("error", f"model stopped calling tools in phase {phase}")
                self._note(f"You are in the {phase} phase. Continue with tools; finish the phase with {' or '.join(sorted(exits))}, or call give_up.")
                continue
            results = [self._run_tool(b, truncated=msg.stop_reason == "max_tokens") for b in uses]
            self.messages.append({"role": "user", "content": results})
            sub, self.ws.submission = self.ws.submission, None
            if sub and (sub[0] in exits or sub[0] == "give_up"):
                if sub[0] == "give_up":
                    self.result.status, self.result.reason = "gave_up", sub[1]["reason"]
                return sub
        raise _Stop("error", f"turn limit reached in phase {phase}")

    def _call_model(self):
        self.result.turns += 1
        with self.client.beta.messages.stream(
            model=self.model,
            max_tokens=64000,
            system=SYSTEM,
            tools=TOOL_SPECS,
            messages=self.messages,
            thinking={"type": "adaptive"},
            output_config={"effort": self.effort},
            cache_control={"type": "ephemeral"},
            betas=["server-side-fallback-2026-07-01"],
            fallbacks="default",
        ) as stream:
            msg = stream.get_final_message()
        for key in ("input_tokens", "output_tokens", "cache_read_input_tokens", "cache_creation_input_tokens"):
            self.result.usage[key] = self.result.usage.get(key, 0) + (getattr(msg.usage, key, 0) or 0)
        self._record({"turn": self.result.turns, "phase": self.ws.phase, "stop_reason": msg.stop_reason,
                      "content": [b.model_dump(mode="json") for b in msg.content]})
        return msg

    def _run_tool(self, block, truncated: bool) -> dict[str, Any]:
        def result(text: str, error: bool = False) -> dict[str, Any]:
            self._record({"tool": block.name, "input": block.input if isinstance(block.input, dict) else str(block.input),
                          "error": error, "result": text[:4000]})
            out = {"type": "tool_result", "tool_use_id": block.id, "content": text}
            if error:
                out["is_error"] = True
            return out

        spec = SPECS_BY_NAME.get(block.name)
        if spec is None:
            return result(f"unknown tool {block.name}", True)
        if truncated:
            return result("Your response hit the output limit and this call was cut off. Send it again, smaller if possible.", True)
        problem = validate_input(spec, block.input)
        if problem:
            return result(f"invalid input: {problem}", True)
        try:
            return result(self.tools[block.name](**block.input))
        except ToolError as exc:
            return result(str(exc), True)
        except Exception as exc:  # a tool bug should not end the run
            return result(f"{type(exc).__name__}: {exc}", True)

    def _note(self, text: str, final: bool = False) -> None:
        """Tell the model what the harness decided, appending to the last user turn."""
        self._record({"harness": text})
        if final:
            return
        last = self.messages[-1]
        if last["role"] == "user" and isinstance(last["content"], list):
            last["content"].append({"type": "text", "text": text})
        else:
            self.messages.append({"role": "user", "content": [{"type": "text", "text": text}]})

    def _record(self, entry: dict[str, Any]) -> None:
        if self._log:
            self._log.write(json.dumps(entry, default=str) + "\n")
            self._log.flush()

    # -- git helpers -----------------------------------------------------
    def _git(self, *args: str) -> str:
        return subprocess.run(["git", *args], cwd=self.ws.root, capture_output=True, text=True,
                              encoding="utf-8", errors="replace").stdout

    def _changed_test_files(self) -> list[str]:
        files = []
        for line in self._git("status", "--porcelain", "--untracked-files=all").splitlines():
            path = line[3:].strip().strip('"')
            if " -> " in path:
                path = path.split(" -> ", 1)[1]
            if is_test_path(path):
                files.append(path)
        return files

    def _read_bytes(self, rel: str) -> bytes | None:
        p = self.ws.root / rel
        return p.read_bytes() if p.is_file() else None

    def _restore_tests(self) -> list[str]:
        tampered = []
        for rel in set(self._changed_test_files()) | set(self.test_snapshot):
            if rel not in self.test_snapshot:
                # a test file that was not touched during reproduction: put it back
                self._git("checkout", "--", rel)
                if (self.ws.root / rel).exists() and self._git("ls-files", rel).strip() == "":
                    (self.ws.root / rel).unlink()
                tampered.append(rel)
                continue
            want = self.test_snapshot[rel]
            if self._read_bytes(rel) != want:
                tampered.append(rel)
                if want is not None:
                    (self.ws.root / rel).write_bytes(want)
        return tampered

    def _diff(self) -> str:
        skip = (":(exclude,glob)**/__pycache__/**", ":(exclude,glob)**/*.pyc")
        self._git("add", "-N", "--", ".", *skip)
        return self._git("diff", "--", ".", *skip)


class _Stop(Exception):
    def __init__(self, status: str, reason: str):
        super().__init__(reason)
        self.status, self.reason = status, reason

